package com.ruoyi.framework.audit;
import java.util.*;import java.nio.file.*;import java.util.concurrent.*;import com.alibaba.fastjson2.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.junit.jupiter.api.Assumptions.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
class AuditQueueDatabaseLiveTest {
 static class IsolatedJdbc extends JdbcTemplate{final String prefix;IsolatedJdbc(DriverManagerDataSource ds,String p){super(ds);prefix=p;}String sql(String s){return s.replaceAll("\\b(audit_outbox|sys_oper_log|sys_logininfor|audit_scope|audit_file_cursor|metal_factory)\\b",prefix+"$1");}public List<Map<String,Object>> queryForList(String s){return super.queryForList(sql(s));}public List<Map<String,Object>> queryForList(String s,Object...args){return super.queryForList(sql(s),args);}public <T>T queryForObject(String s,Class<T> type,Object...args){return super.queryForObject(sql(s),type,args);}public int update(String s,Object...args){return super.update(sql(s),args);}public int update(String s){return super.update(sql(s));}public int[] batchUpdate(String s,List<Object[]> args){return super.batchUpdate(sql(s),args);}}
 @Test void tenThousandEventsConcurrentWorkersRestartDuplicateAndPoison()throws Exception {
  String location=System.getProperty("full.fix.root");assumeTrue(location!=null,"显式本地数据库隔离验收");Map<String,String> env=new HashMap<>();for(String line:Files.readAllLines(Path.of(location,".env"))){int i=line.indexOf('=');if(i>0){String v=line.substring(i+1);if(v.startsWith("'")&&v.endsWith("'"))v=v.substring(1,v.length()-1);env.put(line.substring(0,i),v);}}
  var ds=new DriverManagerDataSource();ds.setDriverClassName("com.mysql.cj.jdbc.Driver");ds.setUrl("jdbc:mysql://127.0.0.1:"+env.getOrDefault("MYSQL_PORT","3308")+"/heavy_metal?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai&rewriteBatchedStatements=true");ds.setUsername(env.get("MYSQL_USER"));ds.setPassword(env.get("MYSQL_PASSWORD"));JdbcTemplate actual=new JdbcTemplate(ds);
  String prefix="audit_test_"+UUID.randomUUID().toString().replace("-","")+"_";assertTrue(prefix.matches("audit_test_[a-f0-9]{32}_"));List<String> tables=List.of("audit_outbox","sys_oper_log","sys_logininfor","audit_scope","audit_file_cursor","metal_factory");List<String> made=new ArrayList<>();ExecutorService pool=Executors.newFixedThreadPool(2);
  try{for(String name:tables){actual.execute("CREATE TABLE "+prefix+name+" LIKE "+name);made.add(prefix+name);}var jdbc=new IsolatedJdbc(ds,prefix);var manager=new DataSourceTransactionManager(ds);List<Object[]> values=new ArrayList<>();for(int i=0;i<10000;i++){var event=event(i);values.add(new Object[]{event.get("event"),JSON.toJSONString(event)});}jdbc.batchUpdate("INSERT INTO audit_outbox(event_id,event_json) VALUES(?,?)",values);
   new AuditDelivery(jdbc,manager).deliver();int first=actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"audit_outbox WHERE status='DELIVERED'",Integer.class);assertTrue(first>0&&first<=1000);
   var tasks=List.of(pool.submit(()->{var worker=new AuditDelivery(jdbc,manager);for(int i=0;i<12;i++)worker.deliver();}),pool.submit(()->{var worker=new AuditDelivery(jdbc,manager);for(int i=0;i<12;i++)worker.deliver();}));for(var future:tasks)future.get(90,TimeUnit.SECONDS);
   assertEquals(10000,actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"audit_outbox WHERE status='DELIVERED'",Integer.class));assertEquals(10000,actual.queryForObject("SELECT (SELECT COUNT(*) FROM "+prefix+"sys_oper_log)+(SELECT COUNT(*) FROM "+prefix+"sys_logininfor)",Integer.class));
   jdbc.update("UPDATE audit_outbox SET status='PENDING' WHERE event_id=?","test-0");new AuditDelivery(jdbc,manager).deliver();assertEquals(5000,actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"sys_oper_log",Integer.class));
   var poison=event(10000);poison.put("time","invalid");var healthy=event(10001);jdbc.batchUpdate("INSERT INTO audit_outbox(event_id,event_json) VALUES(?,?)",List.of(new Object[]{poison.get("event"),JSON.toJSONString(poison)},new Object[]{healthy.get("event"),JSON.toJSONString(healthy)}));new AuditDelivery(jdbc,manager).deliver();assertEquals(1,actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"audit_outbox WHERE status='PENDING' AND attempts>0",Integer.class));assertEquals("DELIVERED",actual.queryForObject("SELECT status FROM "+prefix+"audit_outbox WHERE event_id='test-10001'",String.class));
   Files.writeString(Path.of(location,"outputs/日志队列一万条隔离验收.json"),JSON.toJSONString(Map.of("events",10000,"concurrentWorkers",2,"restart",true,"duplicatesPrevented",true,"poisonIsolated",true,"productionTablesModified",false)));
  }finally{pool.shutdownNow();for(String name:made.reversed()){assertTrue(name.startsWith(prefix));actual.execute("DROP TABLE "+name);}}
 }
 private static JSONObject event(int i){JSONObject e=new JSONObject();e.put("event","test-"+i);e.put("time","2026-10-14T12:00:00");e.put("actor","isolated-test");if(i%2==0){e.put("kind","operation");e.put("title","队列隔离验收");e.put("path","/metal/warehouse-order");e.put("verb","POST");e.put("code","SUCCESS");e.put("request","");e.put("response","");e.put("cost",0);e.put("replayed",false);e.put("factories",List.of());}else{e.put("kind","login");e.put("status","0");}return e;}
}
